import java.util.Iterator;
import java.util.NoSuchElementException;

public class SnapshotableCollection<T> implements Iterable<T> {
    private Object[] elements;
    private int size;

    public SnapshotableCollection(int capacity) {
        elements = new Object[capacity];
        size = 0;
    }

    public void add(T element) {
        if (size >= elements.length) {
            throw new IllegalStateException("Collection is full");
        }
        elements[size++] = element;
    }

    // Memento implementation for state capture and rollback
    public static class CollectionMemento {
        private final Object[] stateSnapshot;
        private final int snapshotSize;

        private CollectionMemento(Object[] elements, int size) {
            this.stateSnapshot = elements.clone();
            this.snapshotSize = size;
        }
    }

    public CollectionMemento save() {
        return new CollectionMemento(elements, size);
    }

    public void restore(CollectionMemento memento) {
        this.elements = memento.stateSnapshot.clone();
        this.size = memento.snapshotSize;
    }

    // Custom Iterator implementation
    @Override
    public Iterator<T> iterator() {
        return new Iterator<T>() {
            private int cursor = 0;

            @Override
            public boolean hasNext() {
                return cursor < size;
            }

            @Override
            @SuppressWarnings("unchecked")
            public T next() {
                if (!hasNext()) {
                    throw new NoSuchElementException();
                }
                return (T) elements[cursor++];
            }
        };
    }
}
